import {getListOrder,setListOrder,orderItems,orderHTML} from './list-order.js?v=27.1';
import {createProvinceModel} from './province-core.js?v=27.1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('pt-BR');
export function createProvinceMenu({D,proposal,canvas,controls,locate,changeMode,onChange,beforeOpen,beforeStroke,focus,selectCity,onSelect,toast,title,cursor,onEconomy,onHistory,onHistoryCard}){
 const model=createProvinceModel(D,proposal),data=model.data,key='silvengard-provinces-v25-'+(D.savedDefaults?.id||'base');
 if(D.defaultProvinceEdits)model.importData(D.defaultProvinceEdits);
 try{const saved=localStorage.getItem(key);if(saved)model.importData(JSON.parse(saved));}catch(e){toast('Províncias: '+e.message);}
 let stateId=13,target=data.provinces.find(p=>p.state===13)?.i,active=false,drawing=false,radius=12,last=null;
 const panel=document.createElement('aside');panel.id='provincePanel';panel.hidden=true;panel.setAttribute('aria-label','Menu de províncias');document.body.append(panel);
 panel.innerHTML=`<div class="provinceHeading"><div><small>DIVISÕES INTERNAS</small><h2>Províncias</h2></div><button id="closeProvinces" aria-label="Fechar províncias">✕</button></div><label>Estado<select id="provinceState">${D.states.filter(s=>s.i).map(s=>`<option value="${s.i}">${esc(s.name.trim())}</option>`).join('')}</select></label>${orderHTML("provinceOrder","Ordenar províncias e localidades")}<div id="provinceSummary"></div><button id="createProvince">+ Criar província</button><div id="provinceCards"></div><section id="provinceInspector"></section><section class="provinceBrush"><label class="provinceCheck"><input id="provincePaint" type="checkbox"> Pincel de limites</label><p id="provinceTarget"></p><label>Raio · <output id="provinceRadiusValue">12</output><input id="provinceRadius" type="range" min="3" max="55" value="12"></label><p class="source">Escolha uma província e arraste no mapa. O pincel transfere somente terra do mesmo estado. Esc desliga; botão direito move o mapa.</p><div class="editorActions"><button id="provinceUndo">↶ Desfazer</button><button id="provinceRedo">↷ Refazer</button></div><p id="provincePaintStatus" role="status"></p></section><button id="provinceExport">Exportar províncias ↓</button><label class="editorImport">Importar províncias<input id="provinceImport" type="file" accept="application/json" hidden></label><p class="source">Edições salvas neste navegador. “Exportar edição” inclui as províncias. “Definir como padrão”, no rodapé, guarda também esta divisão para as próximas aberturas do Atlas.</p>`;
 const $=s=>panel.querySelector(s);
 function status(){
  $('#provinceTarget').textContent='Destino: '+(data.provinces.find(p=>p.i===target)?.name||'escolha uma província');
  $('#provincePaintStatus').textContent=`${fmt(model.exportData().cells.length)} células ajustadas · pincel ${active?'ligado':'desligado'}`;
  $('#provinceUndo').disabled=!model.canUndo;$('#provinceRedo').disabled=!model.canRedo;
 }
 function render(){
  const unsorted=data.provinces.filter(p=>p.state===stateId),stats=new Map(unsorted.map(p=>[p.i,model.stats(p.i)])),ps=orderItems(unsorted,getListOrder(),p=>p.name,p=>stats.get(p.i).population);$('#provinceOrder').value=getListOrder();$('#provinceState').value=stateId;
  $('#provinceSummary').innerHTML=`<b>${ps.length} províncias · ${ps.reduce((n,p)=>n+stats.get(p.i).cities.length,0)} localidades</b><p>${fmt(ps.reduce((n,p)=>n+stats.get(p.i).population,0))} habitantes nas localidades</p>`;
  $('#provinceCards').innerHTML=ps.map(p=>{const s=stats.get(p.i);return `<button class="provinceCard ${p.i===target?'active':''}" data-province="${p.i}"><span class="provinceSwatch" style="background:${p.color}"></span><span><b>${esc(p.name)}</b><small>${s.cities.length} localidades · ${fmt(s.population)} hab.</small></span></button>`;}).join('');
  for(const b of panel.querySelectorAll('[data-province]'))b.onclick=()=>choose(+b.dataset.province);
  const p=data.provinces.find(p=>p.i===target),s=stats.get(target);
  $('#provinceInspector').innerHTML=p&&s?`<label>Nome da província<input id="provinceName" maxlength="100" value="${esc(p.name)}"></label><button id="provinceRename">Salvar nome</button><div class="provinceMetrics"><span><b>${fmt(s.population)}</b>População urbana</span><span><b>${s.cities.length}</b>Localidades</span><span><b>${s.ports}</b>Portos principais</span></div><p class="source">Soma das populações das localidades, sem estimativa rural. A lista acompanha os limites pintados.</p><button id="provinceEconomy">Economia da província</button><h3>Cidades e localidades</h3>${orderItems(s.cities,getListOrder(),title).map(b=>`<button class="provinceTown" data-town="${b.i}"><span>${esc(title(b))}</span><b>${fmt(b.demographics?.population||0)}</b></button>`).join('')||'<p class="muted">Sem localidades nesta divisão.</p>'}<button id="provinceFocus">Localizar província ↗</button><button id="deleteProvince" class="dangerButton" ${s.count||s.cities.length||s.points.length?'disabled':''}>Excluir província</button><p class="source">${s.count?'Para excluir, transfira primeiro toda a área para outra província com o pincel.':'Sem território atribuído. Use o pincel para desenhar a nova província ou exclua-a.'}</p>`:'';
  if(p&&s){onHistoryCard?.($('#provinceInspector'),'province',p.i);$('#provinceEconomy').onclick=()=>{setActive(false);onEconomy?.(p.i);};$('#provinceRename').onclick=()=>{try{model.rename(target,$('#provinceName').value);commit();toast('Nome da província salvo');}catch(e){toast(e.message);}};$('#provinceName').onkeydown=e=>{if(e.key==='Enter')$('#provinceRename').click();};$('#provinceFocus').onclick=()=>focus(...s.center,320);$('#deleteProvince').onclick=()=>{try{setActive(false);model.remove(target);target=data.provinces.find(p=>p.state===stateId)?.i;commit();toast('Província excluída · você pode desfazer');}catch(e){toast(e.message);}};}
  for(const b of panel.querySelectorAll('[data-town]'))b.onclick=()=>{setActive(false);selectCity(+b.dataset.town);};status();
 }
 function choose(id){target=id;const p=data.provinces.find(p=>p.i===id);if(p){stateId=p.state;onSelect(p);}render();}
 function commit(){if(!data.provinces.some(p=>p.i===target))target=data.provinces.find(p=>p.state===stateId)?.i;try{localStorage.setItem(key,JSON.stringify(model.exportData()));}catch{toast('Exporte as províncias para guardar sua edição.');}for(const p of data.provinces)model.stats(p.i);onChange(true);render();}
 function finish(){if(!drawing)return;drawing=false;last=null;controls.enabled=true;if(model.end())commit();}
 function setActive(value){if(!value)finish();active=!!value;$('#provincePaint').checked=active;canvas.style.cursor=active?'crosshair':'grab';if(!active)cursor(null,radius);status();}
 function dab(xy){const start=last||xy,n=Math.max(1,Math.ceil(Math.hypot(xy[0]-start[0],xy[1]-start[1])/Math.max(1,radius*.4)));let count=0;for(let i=1;i<=n;i++)count+=model.paint(start[0]+(xy[0]-start[0])*i/n,start[1]+(xy[1]-start[1])*i/n,radius,target);last=xy;if(count)onChange(false);}
 canvas.addEventListener('pointerdown',e=>{if(!active||e.button!==0)return;e.preventDefault();e.stopImmediatePropagation();const xy=locate(e);if(!xy)return;beforeStroke();drawing=true;controls.enabled=false;model.begin();canvas.setPointerCapture(e.pointerId);dab(xy);},{capture:true});
 canvas.addEventListener('pointermove',e=>{if(!active)return;if(!drawing&&e.buttons){cursor(null,radius);return;}e.stopImmediatePropagation();const xy=locate(e);cursor(xy,radius);if(drawing){e.preventDefault();if(xy)dab(xy);else last=null;}},{capture:true});
 const end=e=>{if((!active&&!drawing)||(e.button!==0&&e.type==='pointerup'))return;e.preventDefault();e.stopImmediatePropagation();finish();if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);};
 canvas.addEventListener('pointerup',end,{capture:true});canvas.addEventListener('pointercancel',end,{capture:true});canvas.addEventListener('lostpointercapture',finish);addEventListener('blur',finish);
 canvas.addEventListener('pointerleave',()=>cursor(null,radius));
 $('#createProvince').onclick=()=>{finish();const d=document.createElement('dialog');d.className='journeyConfirm poiDialog';d.innerHTML='<h2>Criar província</h2><p>'+esc(D.states.find(s=>s.i===stateId)?.name.trim())+'</p><label>Nome da nova província<input id="newProvinceName" maxlength="100" placeholder="Ducado, marca, condado…"></label><div class="editorActions"><button id="cancelNewProvince">Cancelar</button><button id="confirmNewProvince">Criar província</button></div>';document.body.append(d);d.querySelector('#cancelNewProvince').onclick=()=>d.remove();d.querySelector('#confirmNewProvince').onclick=()=>{try{setActive(false);const p=model.create(stateId,d.querySelector('#newProvinceName').value);target=p.i;d.remove();commit();toast('Província criada. Ative o pincel para atribuir território.');}catch(e){toast(e.message);}};d.addEventListener('cancel',()=>d.remove());d.showModal();};$('#provinceOrder').onchange=e=>{setListOrder(e.target.value);render();};$('#provincePaint').onchange=e=>setActive(e.target.checked);$('#provinceRadius').oninput=e=>{radius=+e.target.value;$('#provinceRadiusValue').value=radius;};
 $('#provinceState').onchange=e=>{finish();stateId=+e.target.value;choose(data.provinces.find(p=>p.state===stateId)?.i);};
 $('#provinceUndo').onclick=()=>{finish();if(model.undo())commit();};$('#provinceRedo').onclick=()=>{finish();if(model.redo())commit();};
 function close(){setActive(false);panel.hidden=true;}$('#closeProvinces').onclick=close;
 function importData(raw){finish();model.importData(raw);commit();}
 $('#provinceImport').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>20000000)throw Error('Arquivo muito grande.');const raw=JSON.parse(await file.text());importData(raw.provinceEdits||raw);toast('Províncias importadas');}catch(err){toast(err.message);}finally{e.target.value='';}};
 $('#provinceExport').onclick=()=>{finish();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(model.exportData(),null,2)],{type:'application/json'}));a.download='silvengard-provincias.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);};
 addEventListener('keydown',e=>{if(panel.hidden||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key==='Escape')setActive(false);if((e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();e.stopImmediatePropagation();finish();if(e.key.toLowerCase()==='y'||e.shiftKey?model.redo():model.undo())commit();}},{capture:true});
 for(const p of data.provinces)model.stats(p.i);render();
 return {model,data,open(id=target){beforeOpen();changeMode('provinces');panel.hidden=false;document.querySelector('#detail').hidden=true;choose(id);},close,refresh(){if(!panel.hidden)render();},exportData(){finish();return model.exportData();},importData};
}
